import java.io.*;
public class Main {
    static long[] ones = {0, 1, 11, 111, 1111, 11111, 111111, 1111111, 11111111, 111111111, 1111111111, 11111111111L, 111111111111L, 1111111111111L, 11111111111111L, 111111111111111L, 1111111111111111L};
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());
        long res = decompose(n);
        System.out.println(res);
    }
    public static long decompose(long n) {
        if (n <= 6) return n;
        long digits = getDigits(n);
        long lower = ones[(int) digits];
        long upper;
        if (n < lower) {
            upper = lower;
            lower = ones[(int) (digits - 1)];
        } else if (n > lower) {
            upper = ones[(int) (digits + 1)];
        } else {
            return digits;
        }
        long resLower = decompose(n % lower) + (n / lower) * getDigits(lower);
        long resUpper = Long.MAX_VALUE;
        if (upper - n < n) {
            resUpper = decompose(upper - n) + getDigits(upper);
        }
        return Math.min(resLower, resUpper);
    }
    static long getDigits(long n) {
        long d = 0;
        long t = n;
        while (t > 0) { d++; t /= 10; }
        return d;
    }
}
